// Returns the indices of the top-2 values among (i, j, k), ordered so that
// valores[res.0] >= valores[res.1]. Indices i, j, k are assumed distinct/in-bounds.
fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    let a = valores[i];
    let b = valores[j];
    let c = valores[k];

    // If i is >= both, it's the maximum; pick the larger of j/k as second.
    if a >= b && a >= c {
        if b >= c {
            (i, j)
        } else {
            (i, k)
        }
    }
    // Else if j is >= both, it's the maximum; pick the larger of i/k as second.
    else if b >= a && b >= c {
        if a >= c {
            (j, i)
        } else {
            (j, k)
        }
    }
    // Otherwise k is the maximum; pick the larger of i/j as second.
    else {
        if a >= b {
            (k, i)
        } else {
            (k, j)
        }
    }
}

